<?php session_start(); if(!isset($_SESSION['user_id'])||strtolower($_SESSION['user_type']??'')!=='operator'){header('Location: ../login.php');exit;} require_once '../Includes/csrf.php'; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Operations · MBUS</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><link rel="stylesheet" href="../Assets/css/bottom-nav.css"><style>body{font-family:Inter,system-ui;background:#f6f8fb;color:#162033;margin:0}.wrap{max-width:900px;margin:auto;padding:1.25rem 1rem 7rem}.card{background:#fff;border:1px solid #e5eaf1;border-radius:18px;padding:1rem;margin:1rem 0}.map{height:280px;border-radius:16px;background:linear-gradient(135deg,#dbeafe,#ecfeff);display:grid;place-items:center;color:#285f8f}.pickup{padding:.7rem 0;border-bottom:1px solid #edf1f5}.muted{color:#65748a}</style></head><body><main class="wrap"><h1><i class="fa fa-location-dot"></i> Live operations</h1><p class="muted">Share your location while operating so commuters and admins can see your bus. Waiting requests appear below.</p><section class="card"><div id="map" class="map">Location sharing is starting…</div><p id="state" class="muted">Requesting location permission…</p></section><section class="card"><h2>Waiting passengers</h2><div id="pickups">Loading…</div></section></main><nav class="bottom-nav"><a href="operator_dashboard.php" class="bottom-nav-item"><i class="fa fa-home"></i><span>Home</span></a><a href="manage_trips.php" class="bottom-nav-item"><i class="fa fa-bus"></i><span>Trips</span></a><a href="live_map.php" class="bottom-nav-item active"><i class="fa fa-map-location-dot"></i><span>Live</span></a><a href="scan.php" class="bottom-nav-item"><i class="fa fa-qrcode"></i><span>Scan</span></a><a href="passengers.php" class="bottom-nav-item"><i class="fa fa-users"></i><span>Riders</span></a></nav><script>const csrf=<?php echo json_encode(csrf_get_token()); ?>;async function refresh(){const r=await fetch('../api/get_live_map_data.php',{cache:'no-store'});const j=await r.json();document.getElementById('pickups').innerHTML=j.pickups?.length?j.pickups.map(p=>`<div class="pickup"><strong>${p.full_name}</strong><br>${p.pickup_location}<br><small>${p.bus_number} · ${p.created_at}</small></div>`).join(''):'<p class="muted">No waiting passengers right now.</p>';}function publish(p){const f=new FormData();f.append('csrf_token',csrf);f.append('latitude',p.coords.latitude);f.append('longitude',p.coords.longitude);fetch('../api/update_bus_location.php',{method:'POST',body:f}).then(()=>{document.getElementById('state').textContent='Location shared · updated '+new Date().toLocaleTimeString();document.getElementById('map').innerHTML='<i class="fa fa-location-dot"></i> Your bus location is live';}).catch(()=>document.getElementById('state').textContent='Could not share location.');}if(navigator.geolocation)navigator.geolocation.watchPosition(publish,()=>document.getElementById('state').textContent='Location permission is needed for live tracking.',{enableHighAccuracy:true,maximumAge:15000,timeout:10000});refresh();setInterval(refresh,15000);</script></body></html>
